steps.solution:
function countThankYous(guests, helpers) {
  let thanks = 0
  for (let i = 0; i < guests.length; i++) {
    for (let j = 0; j < helpers.length; j++) {
      thanks = thanks + 1
    }
  }
  return thanks
}

console.log(countThankYous(['Ana', 'Ben'], ['Rosa'])) // 2
